const inputData = $input.first().json;
let parsed = null;

// 1. Já é um objeto estruturado com slides?
if (inputData && Array.isArray(inputData.slides) && inputData.slides.length > 0) {
  parsed = inputData;
} else if (inputData && inputData.output && Array.isArray(inputData.output.slides)) {
  parsed = inputData.output;
} else {
  // 2. Extrai texto de vários formatos possíveis do Gemini
  let rawText = '';
  if (typeof inputData === 'string') {
    rawText = inputData;
  } else if (inputData?.text) {
    rawText = inputData.text;
  } else if (inputData?.content?.parts?.[0]?.text) {
    rawText = inputData.content.parts[0].text;
  } else if (inputData?.candidates?.[0]?.content?.parts?.[0]?.text) {
    rawText = inputData.candidates[0].content.parts[0].text;
  } else if (inputData?.response) {
    rawText = typeof inputData.response === 'string' ? inputData.response : JSON.stringify(inputData.response);
  } else {
    rawText = JSON.stringify(inputData);
  }

  rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      parsed = JSON.parse(jsonMatch[0]);
    } catch (e) {
      parsed = JSON.parse(rawText);
    }
  } else {
    parsed = JSON.parse(rawText);
  }
}

const context = $('Normalizar Variáveis').first().json;
const crmBaseUrl = context.crmBaseUrl || 'https://blacklink-crm.netlify.app';
const totalSlides = parsed.slides ? parsed.slides.length : 5;

const slidesComImagens = (parsed.slides || []).map((slide, index) => {
  const slideNum = slide.slideNumber || index + 1;
  const query = new URLSearchParams({
    slide: String(slideNum),
    total: String(totalSlides),
    headline: slide.headline || slide.title || '',
    body: slide.bodyText || slide.body || '',
    format: context.format || 'carousel'
  });
  const imageUrl = `${crmBaseUrl}/api/marketing/render-slide?${query.toString()}`;
  return {
    slideNumber: slideNum,
    headline: slide.headline || slide.title || `Insight ${slideNum}`,
    bodyText: slide.bodyText || slide.body || '',
    visualPrompt: slide.visualPrompt || 'Dark minimal editorial aesthetic',
    imageUrl
  };
});

const hookHeadline = parsed.hookHeadline || slidesComImagens[0]?.headline || context.theme;
const bodyCopy = parsed.bodyCopy || parsed.postCaption || 'Confira os detalhes neste carrossel estratégico.';
const ctaText = parsed.ctaText || 'Salve este post para consultar depois.';
const hashtags = Array.isArray(parsed.hashtags) ? parsed.hashtags : ['#VendasB2B', '#BlackLink', '#AltaPerformance'];
const postCaption = parsed.postCaption || `${bodyCopy}\n\n${ctaText}\n\n${hashtags.join(' ')}`;

return {
  id: `cr-n8n-${Date.now()}`,
  theme: context.theme,
  format: context.format,
  targetAudience: context.targetAudience,
  hookHeadline,
  bodyCopy,
  ctaText,
  hashtags,
  postCaption,
  slides: slidesComImagens,
  imageUrls: slidesComImagens.map(s => s.imageUrl),
  publishToInstagram: context.publishToInstagram,
  createdAt: new Date().toISOString(),
  source: 'n8n'
};

